-- 依据 wowhead classic zhCN 修正 1.12.1 原生条目的名称
--
-- 为什么查 wowhead：库内原生文本来自社区汉化（mangos-zero Translations 一系），
-- 它本身混入了**台湾译法**（Goblin=哥布林、Troll=食人妖、Undead=不死族、Rogue=盗贼），
-- 参考库 mangos-zero 官方中文文件同样如此（Chinese_Creature.sql 里「哥布林」出现 57 次）。
-- wowhead 的 zhCN 是官方客户端译法（Goblin=地精、Troll=巨魔、Undead=亡灵、Rogue=潜行者）。
--
-- 三方校验规则（tools/dbdiff 里的一次性脚本，见会话归档）：
--   ① wowhead 有该条目  ② 英文名与库内一致（确认是同一条内容）
--   ③ wowhead 确有中文名（排除它自己没译、只回英文的条目）
--
-- 生成时间 2026-10-10。带原值条件、可重复导入。
-- 生效：mangosd 控制台 `.reload locales_quest` / `locales_creature` / `locales_gameobject`

-- 一致性说明：wowhead 对**同一实体**偶尔给出两种写法（如 Anachronos 是「安纳克洛斯」，
-- 而它的巨龙形态却是「安纳克罗斯巨龙形态」；Goma/Felhound 的同名条目它根本没收）。
-- 此类以「库内同名实体互相一致」为准，故 15410/5606/6010 沿用 names_fixes 里的统一写法。

SET NAMES utf8mb4;

